NAV = [('Overview','PALO_BlueprintBench.html'),('3-text synthetic test','PALO_BlueprintBench_Leaderboard.html'),('6-process synthetic test','PALO_BlueprintBench_NextCycle.html'),('Real-document generation','PALO_BlueprintBench_Generation.html'),('Corpus','PALO_BlueprintBench_Corpus.html'),('Method','PALO_BlueprintBench_Method.html')]
GIT = 'https://github.com/sev7enITA/PALO-BlueprintBench'


def navigation(filename):
    links=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==filename else '')+f'>{label}</a>' for label,url in NAV)
    return '<header class="bench-site-header"><div class="bench-shell"><a class="bench-brand" href="PALO_BlueprintBench.html"><img src="assets/logo.webp" width="34" height="34" alt="PALO Framework"><img src="assets/blueprintbench/brand/blueprintbench-logo.png" width="164" height="55" alt="BlueprintBench"></a><nav aria-label="Research navigation">'+links+'</nav></div></header>'


def footer():
    return '<footer class="bench-site-footer"><div class="bench-shell"><p>PALO BlueprintBench · Research programme · Maintainer-led tests</p><nav aria-label="Research resources"><a href="PALO_BlueprintBench_Diagnostics.html">Reviewer diagnostics</a><a href="'+GIT+'">Repository and reproducibility</a><a href="PALO_BlueprintBench_Method.html#participation">Contribute a review</a><a href="index.html">PALO Framework</a></nav></div></footer>'


def page_graph(key):
    filename,title,description=PAGES[key];url=SITE+filename
    page={'@type':'WebPage','@id':url+'#webpage','url':url,'name':title+' | BlueprintBench' if key!='overview' else title,'description':description,
          'inLanguage':'en','version':research_publication.PRESENTATION_REVISION,'dateModified':'2026-11-11',
          'isAccessibleForFree':True,'creativeWorkStatus':'Maintainer-led research; provisional labels; independent human validation pending',
          'image':SITE+'assets/blueprintbench/brand/blueprintbench-logo.png',
          'relatedLink':[SITE+path for _,path in NAV if path!=filename]}
    graph=[page,{'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':[
        {'@type':'ListItem','position':1,'name':'PALO BlueprintBench','item':SITE+PAGES['overview'][0]}]+([] if key=='overview' else [{'@type':'ListItem','position':2,'name':title,'item':url}])}]
    page['breadcrumb']={'@id':url+'#breadcrumb'}
    if key=='method':
        references=json.loads((ROOT/'docs/benchmark-references.json').read_text(encoding='utf-8'))
        ref_id=url+'#benchmark-reference-review'
        graph.append({'@type':'WebPageElement','@id':ref_id,'url':url+'#references','name':'Related benchmarks and evaluation methods',
            'description':f"{len(references['entries'])} methodological references. External suites have not been executed for BlueprintBench; citations do not constitute validation or affiliation.",
            'dateModified':references['checked_on'],'citation':[r['source_url'] for r in references['entries']]})
        page['hasPart']=[{'@id':ref_id}]
    return {'@context':'https://schema.org','@graph':graph}


def status():
    return '<aside class="bench-evidence" aria-label="Evidence status"><strong>Evidence status</strong><p>Published observations are maintainer-led tests with provisional labels and automated advisory review. Independent human adjudication and validation are pending. No qualified quality ranking or PALO Blueprint Index is assigned.</p></aside>'


def scope(items):
    return '<dl class="bench-scope">'+''.join('<div><dt>'+html.escape(k)+'</dt><dd>'+html.escape(v)+'</dd></div>' for k,v in items)+'</dl>'


def overview():
    markup = '''<section class="bench-hero"><p class="bench-kicker">Document-to-specification evaluation</p><h1>PALO BlueprintBench</h1><p class="bench-lead">Assessing how AI systems preserve business requirements when they turn documents into structured specifications.</p><p>Business documents contain permissions, obligations, exceptions, responsibilities and conditions. An apparently plausible specification can change their meaning. BlueprintBench examines these transformations, records the supporting source text and makes disagreements available for review.</p><div class="bench-actions"><a href="PALO_BlueprintBench_Generation.html">Real-document generation</a><a href="PALO_BlueprintBench_Method.html">Read the method</a></div></section><p class="bench-evidence">Internal tests with provisional reference answers. <a href="PALO_BlueprintBench_Method.html#qualification">Review status and limitations</a>.</p><section class="bench-section" aria-labelledby="purpose"><h2 id="purpose">What the research measures</h2><div class="bench-three"><article><h3>Interpretation</h3><p>Whether an output preserves the source's scope, modality, exceptions and responsible actors. Provisional label agreement is reported separately from independently adjudicated correctness.</p></article><article><h3>Specification generation</h3><p>Whether a system can generate a structured, source-linked process description. Format checks establish whether an output can be inspected, not whether its meaning is correct.</p></article><article><h3>Operational evidence</h3><p>Completion, missing outputs, observed token use, provider-reported charges and request duration. Each observation retains the model, serving settings and collection conditions.</p></article></div></section><section class="bench-section" aria-labelledby="tests"><h2 id="tests">Choose a test</h2><p>These are separate studies with different inputs and tasks. Their results are not combined into one score.</p><div class="bench-three bench-test-cards"><article id="explorer"><span class="bench-number">01</span><h3>3-text synthetic test</h3><p>Three short fictional procurement texts. Eighteen model configurations perform source-linked translation and statement verification, with three repetitions.</p><p>Useful for inspecting compatibility, label disagreements and incomplete requests.</p><a href="PALO_BlueprintBench_Leaderboard.html">Explore model results</a></article><article><span class="bench-number">02</span><h3>6-process synthetic test</h3><p>Six fictional process descriptions, 48 propositions and six workflow tasks. Three models are tested once, with document-order and threshold variations.</p><p>Useful for examining difficult interpretation choices and draft process decisions.</p><a href="PALO_BlueprintBench_NextCycle.html">Explore the six-process test</a></article><article><span class="bench-number">03</span><h3>Real-document generation</h3><p>A separate study of specification generation from three public document inputs. Three model IDs and three repetitions per input. A separate Google serving-provider supplement brings the total to four configurations, with original failed assignments retained.</p><p>Consult the study page for source coverage and recorded execution status.</p><a href="PALO_BlueprintBench_Generation.html">Explore document generation</a></article></div></section><section class="bench-section"><h2>How this supports system selection</h2><p>Inspect the documents and task before comparing outputs. Identify disagreements that matter for your process, review the evidence behind them, and examine whether the tested provider configuration fits your operational constraints. The current findings support a focused evaluation plan; they do not identify a universally best model or certify a production system.</p><ol class="bench-flow"><li>Choose relevant inputs</li><li>Inspect generated specifications</li><li>Review disputed interpretations</li><li>Check serving conditions</li></ol></section><section class="bench-section bench-two"><article id="cases"><h2>Source material</h2><p>The corpus register distinguishes fictional text, fictional process descriptions, public documents and earlier adapter diagnostics.</p><a href="PALO_BlueprintBench_Corpus.html">Inspect the corpus</a></article><article id="method"><h2>Method and related research</h2><p>Task definitions, scoring boundaries, reviewer roles and the requirements for independent validation.</p><a href="PALO_BlueprintBench_Method.html">Read the method</a> · <a id="references" href="PALO_BlueprintBench_Method.html#references">Related benchmarks</a></article></section>'''

    # Put the three concrete choices immediately after the introduction.
    start = markup.index('<section class="bench-section" aria-labelledby="purpose">')
    middle = markup.index('<section class="bench-section" aria-labelledby="tests">', start)
    end = markup.index('<section class="bench-section"><h2>How this supports', middle)
    return markup[:start] + markup[middle:end] + markup[start:middle] + markup[end:]


def method():
    references=build_references.render(ROOT)[2]
    return '''<section class="bench-hero"><p class="bench-kicker">Research method</p><h1>Method</h1><p class="bench-lead">The unit of evaluation is a configured system performing a defined document task.</p><p>Model identity alone does not describe an experiment. The request, source material, serving provider, reasoning setting, output limit, parsing contract and review procedure affect the observed result.</p></section>'''+status()+'''<section class="bench-section"><h2>Tasks and evidence</h2><div class="bench-three"><article><h3>Statement verification</h3><p>A source text and candidate statement are supplied together. The system classifies whether the statement is supported, contradicted, not established, or affected by an unresolved conflict where the test rubric permits it.</p></article><article><h3>Specification generation</h3><p>The system proposes entities, rules and process decisions from the source. Outputs retain references so reviewers can assess meaning, missing requirements and unsupported additions.</p></article><article><h3>Controlled variations</h3><p>Document order or a stated condition is varied. Relations between paired outputs are examined. A variation that also changes the question batch cannot isolate a single causal factor.</p></article></div></section><section class="bench-section"><h2>Reading the results</h2><div class="bench-two"><article><h3>Fixed assignments and missingness</h3><p>Assigned requests remain in the record when they fail or are not run. Missing output, rejected structure and disagreement with a provisional label are different outcomes. No missing charge is converted to zero.</p></article><article><h3>Structure and meaning</h3><p>A valid JSON object or source reference can still express the wrong rule. Structural acceptance is a contract check. Label agreement is descriptive until the labels and rubric have been adjudicated independently.</p></article><article><h3>Costs, time and context</h3><p>Reported token usage and charges describe the retained requests. Maximum configured output and advertised context capacity are separate from observed prompt length. Different tokenisers, settings and scheduling prevent uncontrolled efficiency rankings.</p></article><article><h3>Disputes and changes</h3><p>Frozen primary labels remain visible. Predeclared exclusions, postrun ambiguity notes and sensitivity analyses are identified separately. Model agreement is advisory evidence, not majority-vote gold.</p></article></div></section><section class="bench-section" id="execution"><h2>Execution and provenance</h2><p>The model-result studies use the <strong>OpenRouter API</strong>, with the serving provider recorded separately where the receipt supplies it. A provider pin and the returned provider are not the same field. Missing identity details remain unavailable. These API measurements do not establish local hardware performance.</p><p>Reviewer diagnostics use separate collection channels, including APIs, a browser, desktop applications and a local model server. Their prompts and observation conditions differ from those used to produce the model results. <a href="PALO_BlueprintBench_Diagnostics.html">Review those diagnostic records separately</a>.</p><p>In this method, a <em>test</em> identifies the input set and task. A <em>run</em> is one recorded execution. A <em>configuration</em> identifies the model and serving settings. Archived files may retain older terms such as campaign or case; those identifiers do not create additional independent datasets.</p></section><section class="bench-section" id="qualification"><h2>Requirements for independent validation</h2><ol class="bench-requirements"><li>Domain experts construct and adjudicate reference propositions, including alternatives and prohibited inferences.</li><li>An external custodian retains source sets outside the system-development process.</li><li>The measure is tested against known semantic defects and false alarms.</li><li>Repeated runs use an appropriate sampling design and uncertainty analysis.</li><li>An independent party reproduces the evaluation and signs the review record.</li></ol><p>These requirements are pending. Automated reviews can identify problems, but cannot substitute for independent domain expertise or custody. <a href="https://github.com/sev7enITA/PALO-BlueprintBench/blob/main/docs/qualification-roadmap.md">Inspect the qualification roadmap</a>.</p></section><section class="bench-section" id="governance"><h2>Governance and limitations</h2><p>PALO maintains both Workbench and BlueprintBench. That relationship is a declared conflict of interest. The current observations do not certify Workbench, demonstrate organisation-wide document processing, or establish a production governance control. Source reuse conditions and provider-specific configuration limits remain part of each evidence record.</p><p>The evaluator release and the presentation revision have separate identities. Historical evidence retains its original bytes. The earlier evaluator 0.2 package is not the corrected evaluator. <a href="https://github.com/sev7enITA/PALO-BlueprintBench/releases">Inspect versioned releases</a>.</p></section>'''+references+'''<section class="bench-section" id="participation"><h2>Contribute to review</h2><p>The next stage needs procurement-domain annotators, an external custodian and an independent methods reviewer. Reviewers should state their role and conflicts, assess source material before seeing model identities, and retain pre-adjudication judgments.</p><p><a href="https://github.com/sev7enITA/PALO-BlueprintBench/blob/main/docs/reviewer-kit.md">Read the reviewer kit</a> · <a href="mailto:info@paloframework.org">Contact the project</a>. Do not send confidential business documents or personal datasets.</p></section>'''


def corpus():
    bank=json.loads((ROOT/'study/next-cycle/case-bank.json').read_text(encoding='utf-8'))
    packets_path=ROOT/'internal_tests/2026-11-11-real-procurement/source-packets.json'
    packets=json.loads(packets_path.read_text(encoding='utf-8')) if packets_path.exists() else []
    public_docs=''.join('<article><h3>'+html.escape(doc['title'])+'</h3><p>'+html.escape(doc['edition'])+' · '+str(doc['supplied_page_count'])+' supplied pages.</p><p><a href="'+html.escape(doc['source_url'],quote=True)+'">Issuing-body source</a> · <a href="'+html.escape(doc['retrieved_from'],quote=True)+'">Retrieved edition</a></p><details><summary>Source coverage and integrity</summary><p>'+html.escape(doc['extraction'])+'</p><p>Supplied physical PDF pages: '+html.escape(str(doc['supplied_page_numbers'][0])+' to '+str(doc['supplied_page_numbers'][-1])+' inclusive')+'. Parent document: '+str(doc['parent_pdf_pages'])+' pages. Extracted source text: '+format(doc['source_character_count'],',')+' characters.</p><p>Source PDF SHA-256: <code>'+html.escape(doc['pdf_sha256'])+'</code></p><p>'+html.escape(doc['exposure'])+'</p><p>'+html.escape(doc['rights'])+'</p></details></article>' for doc in packets)
    six=''.join('<li><strong>'+html.escape(item['title'])+'</strong><span>'+str(len(item['probes']))+' propositions</span></li>' for item in bank['cases'])
    return '''<section class="bench-hero"><p class="bench-kicker">Source register</p><h1>Corpus</h1><p class="bench-lead">Three separate input sets, with different tasks and evidence status.</p><p>Synthetic means written for the experiment. Public documents come from an external issuing body. Neither category is automatically independent test material or a validated reference answer.</p></section>'''+status()+'''<section class="bench-section" id="three-text"><h2>3-text synthetic test</h2>'''+scope([('Input','3 short fictional procurement texts'),('Task','Source-linked translation and statement verification'),('Models','18 configurations across retained collection groups'),('Repetitions','3 per assigned task'),('Execution','OpenRouter API; serving provider in receipts')])+'''<p>The texts describe invoice matching, purchase approval and vendor onboarding. Together they contain 36 source rules and 108 candidate statements. All were authored within the development process. This is one authoring provenance group, not three independently sourced organisations.</p><p><a href="PALO_BlueprintBench_Leaderboard.html">Model results and configuration roster</a> · <a href="https://github.com/sev7enITA/PALO-BlueprintBench/blob/main/internal_tests/2026-11-11-frontier/corpus.json">Source texts and provisional labels on GitHub</a></p></section><section class="bench-section" id="six-process"><h2>6-process synthetic test</h2>'''+scope([('Input','6 fictional process descriptions'),('Task','48 propositions, 6 workflow tasks and 7 paired variations'),('Models','3 configurations: OpenAI, Anthropic and Google'),('Repetitions','1 per assigned task'),('Execution','60 requests through OpenRouter API')])+'''<p>The process descriptions introduce exceptions, scope conditions, dependencies and conflicting interpretations. They share one automated authoring provenance group. The source bank is exposed development material; its labels await human adjudication.</p><ul class="bench-source-list">'''+six+'''</ul><p><a href="PALO_BlueprintBench_NextCycle.html">Results, exact source packets and advisory notes</a> · <a href="https://github.com/sev7enITA/PALO-BlueprintBench/blob/main/study/next-cycle/case-bank.json">Source bank on GitHub</a></p></section><section class="bench-section" id="real-documents"><h2>Real-document generation</h2>'''+scope([('Input','3 public procurement documents; 200 supplied pages'),('Task','Generate a structured specification from source documents'),('Models','3 configurations; see the study page'),('Repetitions','3 planned repetitions per input and configuration'),('Execution','OpenRouter API through MCP; status on the study page')])+'''<p>This study uses externally issued documents rather than fictional source text. The document register records editions, URLs, retained bytes, extraction coverage and reuse conditions. Its generated outputs require source-based human review; public availability does not make a reference answer independent or complete.</p><div class="bench-three bench-public-documents">'''+public_docs+'''</div><p><a href="PALO_BlueprintBench_Generation.html">Document inventory, execution status and generated outputs</a></p></section><section class="bench-section" id="adapter-diagnostics"><h2>Adapter diagnostics</h2>'''+scope([('Input','3 short excerpts from public documents, 4,994 UTF-8 bytes'),('Task','Historical PALO extraction-contract checks'),('Models','10 historical configurations'),('Repetitions','1 assigned call per excerpt'),('Execution','Historical API records; incomplete and differing configurations')])+'''<p>These excerpts concern planning documents and aircraft weighing. They are not the three synthetic procurement texts described above. Their structural acceptance counts diagnose adapter behaviour; they do not measure semantic quality or demonstrate processing of the larger source repositories.</p><p><a href="PALO_BlueprintBench_Leaderboard.html?cohort=historical">Inspect adapter diagnostics</a> · <a href="https://github.com/sev7enITA/PALO-BlueprintBench/tree/main/evidence/development-2026-11-10">Retained historical evidence</a></p></section><section class="bench-section"><h2>Reference answers and review</h2><p>Current synthetic labels are provisional, including the disputed P002, P013 and P036 items. Automated advisory responses are retained separately from human annotation templates. Changes made after observing a response do not silently redefine the original result.</p><p><a href="PALO_BlueprintBench_Method.html#qualification">Independent-validation requirements</a> · <a href="PALO_BlueprintBench_Diagnostics.html">Reviewer collection diagnostics</a></p></section>'''


def page(key):
    filename,title,description=PAGES[key]
    payload=json.dumps(page_graph(key),ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'none'"><title>{html.escape(title)} | Document-to-specification research</title><meta name="description" content="{html.escape(description,quote=True)}"><meta name="palo-publication-revision" content="{research_publication.PRESENTATION_REVISION}"><meta name="palo-release-tag" content="v0.3.0-internal.1"><link rel="canonical" href="{SITE+filename}"><link rel="icon" href="assets/logo.webp" type="image/webp"><link rel="stylesheet" href="assets/blueprintbench/site-architecture.css?v=20261111-6"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:url" content="{SITE+filename}"><meta property="og:image" content="{SITE}assets/blueprintbench/brand/blueprintbench-logo.png"><script type="application/ld+json">{payload}</script></head><body><a class="bench-skip" href="#main">Skip to content</a>{navigation(filename)}<main id="main" class="bench-shell bench-architecture">{globals()[key]()}</main>{footer()}</body></html>\n'''


def apply_navigation(text, filename):
    text=re.sub(r'<header\b[^>]*>.*?</header>',lambda _:navigation(filename),text,count=1,flags=re.S)
    if '<footer' in text:
        text=re.sub(r'<footer\b[^>]*>.*?</footer>',lambda _:footer(),text,count=1,flags=re.S)
    else:text=text.replace('</body>',footer()+'</body>')
    if 'assets/blueprintbench/site-architecture.css' not in text:
        text=text.replace('</head>','<link rel="stylesheet" href="assets/blueprintbench/site-architecture.css?v=20261111-6">\n</head>')
    if filename == 'PALO_BlueprintBench_Diagnostics.html':
        def update_schema(match):
            graph=json.loads(match[1])
            graph['version']=research_publication.PRESENTATION_REVISION
            graph['relatedLink']=[SITE+'PALO_BlueprintBench_Method.html#qualification',SITE+'PALO_BlueprintBench_Corpus.html']
            return '<script type="application/ld+json">'+json.dumps(graph,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')+'</script>'
        text=re.sub(r'<script[^>]*type="application/ld\+json"[^>]*>(.*?)</script>',update_schema,text,flags=re.S)
    return text


def outputs():
    out={ROOT/'web'/filename:page(key).encode('utf-8') for key,(filename,_,_) in PAGES.items()}
    for filename in ['PALO_BlueprintBench_Leaderboard.html','PALO_BlueprintBench_NextCycle.html','PALO_BlueprintBench_Diagnostics.html']:
        path=ROOT/'web'/filename
        out[path]=apply_navigation(path.read_text(encoding='utf-8'),filename).encode('utf-8')
    return out


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args()
    bad=[]
    for path,body in outputs().items():
        if args.check:
            if not path.exists() or path.read_bytes()!=body:bad.append(path.name)
        else:path.write_bytes(body)
    if bad:raise SystemExit('Site architecture drift: '+', '.join(bad))
    print('Research site architecture '+('verified' if args.check else 'built'))
